--

CREATE TABLE public.catalogo_servicio (
    id bigint NOT NULL,
    creado_en timestamp with time zone NOT NULL,
    actualizado_en timestamp with time zone NOT NULL,
    nombre character varying(150) NOT NULL,
    descripcion text NOT NULL,
    instrucciones text NOT NULL,
    activo boolean NOT NULL,
    alcance_visibilidad character varying(20) NOT NULL,
    categoria_id bigint NOT NULL,
    formulario_id bigint,
    tipo character varying(20) NOT NULL,
    workflow_id bigint,
    politica_entrega character varying(30) NOT NULL,
    dias_observacion smallint,
    configuracion_ejecucion_activa_id bigint,
    tiempo_objetivo_cantidad smallint,
    tiempo_objetivo_unidad character varying(10) NOT NULL,
    tiempo_objetivo_habiles boolean NOT NULL,
    politica_prorroga character varying(30) NOT NULL,
    prorroga_aprobador_usuario_id bigint,
    prorroga_aprobador_equipo_id bigint,
    es_ticket_general boolean NOT NULL,
    datos_inicio_en_ejecucion boolean NOT NULL,
    cancelacion_con_aprobacion boolean NOT NULL,
    cancelacion_aprobador_usuario_id bigint,
    cancelacion_aprobador_equipo_id bigint,
    CONSTRAINT catalogo_servicio_dias_observacion_check CHECK ((dias_observacion >= 0)),
    CONSTRAINT catalogo_servicio_tiempo_objetivo_cantidad_check CHECK ((tiempo_objetivo_cantidad >= 0)),
    CONSTRAINT ck_servicio_cancelacion_coherente CHECK ((((cancelacion_aprobador_equipo_id IS NULL) AND (cancelacion_aprobador_usuario_id IS NOT NULL) AND cancelacion_con_aprobacion) OR ((cancelacion_aprobador_equipo_id IS NOT NULL) AND (cancelacion_aprobador_usuario_id IS NULL) AND cancelacion_con_aprobacion) OR ((cancelacion_aprobador_equipo_id IS NULL) AND (cancelacion_aprobador_usuario_id IS NULL) AND (NOT cancelacion_con_aprobacion)))),
    CONSTRAINT ck_servicio_politica_entrega_coherente CHECK ((((dias_observacion >= 1) AND (dias_observacion IS NOT NULL) AND ((politica_entrega)::text = 'PERIODO_OBSERVACIONES'::text)) OR ((NOT ((politica_entrega)::text = 'PERIODO_OBSERVACIONES'::text)) AND (dias_observacion IS NULL)))),
    CONSTRAINT ck_servicio_prorroga_coherente CHECK (((((politica_prorroga)::text = 'CON_APROBACION'::text) AND (prorroga_aprobador_equipo_id IS NULL) AND (prorroga_aprobador_usuario_id IS NOT NULL)) OR (((politica_prorroga)::text = 'CON_APROBACION'::text) AND (prorroga_aprobador_equipo_id IS NOT NULL) AND (prorroga_aprobador_usuario_id IS NULL)) OR ((NOT ((politica_prorroga)::text = 'CON_APROBACION'::text)) AND (prorroga_aprobador_equipo_id IS NULL) AND (prorroga_aprobador_usuario_id IS NULL)))),
    CONSTRAINT ck_servicio_ticket_general_es_servicio CHECK (((NOT es_ticket_general) OR ((tipo)::text = 'SERVICIO'::text))),
    CONSTRAINT ck_servicio_tiempo_objetivo_coherente CHECK ((((tiempo_objetivo_cantidad IS NULL) AND (NOT tiempo_objetivo_habiles) AND ((tiempo_objetivo_unidad)::text = ''::text)) OR ((tiempo_objetivo_cantidad >= 1) AND (tiempo_objetivo_cantidad IS NOT NULL) AND ((tiempo_objetivo_unidad)::text = ANY ((ARRAY['HORAS'::character varying, 'DIAS'::character varying])::text[])))))
);


ALTER TABLE public.catalogo_servicio OWNER TO orbita;

