--
-- Name: tickets_ticket; Type: TABLE; Schema: public; Owner: orbita
--

CREATE TABLE public.tickets_ticket (
    id bigint NOT NULL,
    creado_en timestamp with time zone NOT NULL,
    actualizado_en timestamp with time zone NOT NULL,
    tipo character varying(20) NOT NULL,
    estado character varying(20) NOT NULL,
    origen character varying(20) NOT NULL,
    solicitante_id bigint,
    radicado uuid,
    radicado_en timestamp with time zone,
    equipo_responsable_id bigint,
    usuario_responsable_id bigint,
    instancia_workflow_id bigint,
    entregables_materializados boolean NOT NULL,
    entrega_politica character varying(30) NOT NULL,
    entrega_dias_observacion smallint,
    tiempo_objetivo_cantidad smallint,
    tiempo_objetivo_unidad character varying(10) NOT NULL,
    tiempo_objetivo_habiles boolean NOT NULL,
    fecha_objetivo_original timestamp with time zone,
    fecha_objetivo_vigente timestamp with time zone,
    prorroga_politica character varying(30) NOT NULL,
    prorroga_aprobador_usuario_id bigint,
    prorroga_aprobador_equipo_id bigint,
    consecutivo integer,
    etiqueta character varying(60) NOT NULL,
    datos_inicio_en_ejecucion boolean NOT NULL,
    reglas_finalizacion jsonb,
    notificaciones jsonb,
    cancelacion_con_aprobacion boolean NOT NULL,
    cancelacion_aprobador_usuario_id bigint,
    cancelacion_aprobador_equipo_id bigint,
    CONSTRAINT ck_ticket_cancelacion_coherente CHECK ((((cancelacion_aprobador_equipo_id IS NULL) AND (cancelacion_aprobador_usuario_id IS NOT NULL) AND cancelacion_con_aprobacion) OR ((cancelacion_aprobador_equipo_id IS NOT NULL) AND (cancelacion_aprobador_usuario_id IS NULL) AND cancelacion_con_aprobacion) OR ((cancelacion_aprobador_equipo_id IS NULL) AND (cancelacion_aprobador_usuario_id IS NULL) AND (NOT cancelacion_con_aprobacion)))),
    CONSTRAINT ck_ticket_fechas_objetivo_coherentes CHECK ((((fecha_objetivo_original IS NULL) AND (fecha_objetivo_vigente IS NULL)) OR ((fecha_objetivo_original IS NOT NULL) AND (fecha_objetivo_vigente IS NOT NULL) AND (tiempo_objetivo_cantidad IS NOT NULL)))),
    CONSTRAINT ck_ticket_programacion_es_proceso CHECK (((NOT ((origen)::text = 'PROGRAMACION'::text)) OR ((tipo)::text = 'PROCESO'::text))),
    CONSTRAINT ck_ticket_prorroga_coherente CHECK ((((prorroga_aprobador_equipo_id IS NULL) AND (prorroga_aprobador_usuario_id IS NOT NULL) AND ((prorroga_politica)::text = 'CON_APROBACION'::text)) OR ((prorroga_aprobador_equipo_id IS NOT NULL) AND (prorroga_aprobador_usuario_id IS NULL) AND ((prorroga_politica)::text = 'CON_APROBACION'::text)) OR ((NOT ((prorroga_politica)::text = 'CON_APROBACION'::text)) AND (prorroga_aprobador_equipo_id IS NULL) AND (prorroga_aprobador_usuario_id IS NULL)))),
    CONSTRAINT ck_ticket_solicitante_segun_origen CHECK (((((origen)::text = 'PROGRAMACION'::text) AND (solicitante_id IS NULL)) OR ((NOT ((origen)::text = 'PROGRAMACION'::text)) AND (solicitante_id IS NOT NULL)))),
    CONSTRAINT ck_ticket_tiempo_objetivo_coherente CHECK ((((tiempo_objetivo_cantidad IS NULL) AND (NOT tiempo_objetivo_habiles) AND ((tiempo_objetivo_unidad)::text = ''::text)) OR ((tiempo_objetivo_cantidad >= 1) AND (tiempo_objetivo_cantidad IS NOT NULL) AND ((tiempo_objetivo_unidad)::text = ANY ((ARRAY['HORAS'::character varying, 'DIAS'::character varying])::text[]))))),
    CONSTRAINT tickets_ticket_consecutivo_check CHECK ((consecutivo >= 0)),
    CONSTRAINT tickets_ticket_entrega_dias_observacion_check CHECK ((entrega_dias_observacion >= 0)),
    CONSTRAINT tickets_ticket_tiempo_objetivo_cantidad_check CHECK ((tiempo_objetivo_cantidad >= 0))
);


